import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.23.0";
import { z as z2 } from "npm:zod@^3.25.76";
var get_product_default = defineTool2({
  name: "get_product",
  title: "Get product",
  description: "Get full details for a single product by its numeric id.",
  inputSchema: {
    id: z2.number().int().positive().describe("Product id (matches the 'id' column in the catalog).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: true },
  handler: async ({ id }) => {
    const products = await fetchProducts();
    const product = products.find((p) => p.id === id);
    if (!product) {
      return {
        content: [{ type: "text", text: `Nenhum produto encontrado com id ${id}.` }],
        isError: true
      };
    }
    return {
      content: [{ type: "text", text: JSON.stringify(product, null, 2) }],
      structuredContent: { product }
    };
  }
});

