import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.23.0";
import { z as z3 } from "npm:zod@^3.25.76";
var search_products_default = defineTool3({
  name: "search_products",
  title: "Search products",
  description: "Search the catalog by keyword. Matches product name, description, category, materials and community/people of origin.",
  inputSchema: {
    query: z3.string().trim().min(1).describe("Search terms (Portuguese or English)."),
    limit: z3.number().int().positive().max(50).optional().describe("Max results (default 20).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: true },
  handler: async ({ query, limit }) => {
    const q = query.toLowerCase();
    const all = await fetchProducts();
    const matches = all.filter((p) => {
      const hay = [
        p.name,
        p.description,
        p.longDescription,
        p.category,
        p.materials,
        p.peopleOrCommunity,
        p.originLocation
      ].filter(Boolean).join(" ").toLowerCase();
      return hay.includes(q);
    });
    const results = matches.slice(0, limit ?? 20);
    return {
      content: [
        {
          type: "text",
          text: `${results.length} de ${matches.length} resultado(s) para "${query}".

${results.map((p) => `#${p.id} \u2014 ${p.name} \u2014 R$ ${p.price.toFixed(2)} \u2014 ${p.productUrl}`).join("\n")}`
        }
      ],
      structuredContent: { results, totalMatches: matches.length }
    };
  }
});

